scripts.script:
L = graph10.number("L")
k = graph10.number("k_r")
x00 = graph10.number("x_{0}")

line1 = "검은색 점을 드래그해 빨간색 점과 최대한 일치하도록 로그함수를 그려 보세요."
line2 = "로그함수의 방정식은 다음과 같습니다:"
line3a = "`y = \frac{${L}}{1 + e^{-${k}(x - ${x00})}}`"
line3b = "`y = \frac{${L}}{1 + e^{-${k}x}}`"
line4 = "2015년의 스타벅스 매장 수는 몇 개인가요?"
line5 = "아래에 예측 결과를 입력해 주세요.

참고: 2015년의 매장 수를 구하려면 x에 23을 대입해야 합니다. (2015-1992)"

content:
	when (x00 > 0) "${line1}

${line2}

${line3a}

${line4}

${line5}"
	otherwise "${line1}

${line2}

${line3b}

${line4}

${line5}"

